slides.code:
// Estrutura que representa uma página física no kernel
struct page {
    unsigned long flags;      // status da página (dirty, locked...)
    atomic_t _refcount;       // contador de referências
    struct address_space *mapping;
    // ... outros campos
};

// Estrutura que representa o espaço de memória de um processo
struct mm_struct {
    struct vm_area_struct *mmap;  // lista de VMAs
    pgd_t *pgd;                   // ponteiro para a page table global
    unsigned long start_code, end_code;
    unsigned long start_data, end_data;
    unsigned long start_brk, brk; // heap
    unsigned long start_stack;    // pilha
};
